import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-schema-design-l3-001', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What does Third Normal Form (3NF) eliminate that Second Normal Form (2NF) does not?', options: ['Repeating groups', 'Partial dependencies', 'Transitive dependencies — non-key columns must not depend on other non-key columns', 'Multi-valued dependencies'], correctAnswer: 2, explanation: '3NF requires that every non-key attribute depends only on the primary key, not on other non-key attributes. This eliminates transitive dependencies where A→B→C would cause redundancy.', codeSnippet: "-- Violation: department_name depends on department_id, not on employee_id\nCREATE TABLE employees_bad (\n  employee_id INT PRIMARY KEY,\n  department_id INT,\n  department_name TEXT  -- transitive dependency!\n);\n\n-- 3NF fix: separate tables\nCREATE TABLE departments (department_id INT PRIMARY KEY, name TEXT);\nCREATE TABLE employees (employee_id INT PRIMARY KEY, department_id INT REFERENCES departments);", tags: ['schema-design', 'normalization', '3nf'] },
  { id: 'pg-schema-design-l3-002', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Boyce-Codd Normal Form (BCNF)?', options: ['Same as 3NF', 'A stricter version of 3NF where every determinant must be a candidate key', 'A form that eliminates all joins', 'A form requiring no NULLable columns'], correctAnswer: 1, explanation: 'BCNF strengthens 3NF by requiring that for every functional dependency X→Y, X must be a superkey. This handles cases where 3NF allows dependencies on parts of overlapping candidate keys.', tags: ['schema-design', 'normalization', 'bcnf'] },
  { id: 'pg-schema-design-l3-003', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'When is intentional denormalization appropriate?', options: ['Always for faster writes', 'Never — normalization must always be maintained', 'When read-heavy workloads benefit from pre-joined data and the redundancy trade-off is acceptable', 'Only when disk space is unlimited'], correctAnswer: 2, explanation: 'Denormalization introduces controlled redundancy to reduce the number of JOINs required for frequent read queries. It trades write complexity (maintaining consistency) for read performance. Common in data warehousing and reporting schemas.', tags: ['schema-design', 'denormalization', 'performance'] },
  { id: 'pg-schema-design-l3-004', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What is declarative table partitioning in PostgreSQL?', options: ['Manually splitting data into separate tables', 'A built-in feature where you define a partitioned parent table and PostgreSQL automatically routes rows to the correct child partition', 'Splitting a database across servers', 'Creating read replicas'], correctAnswer: 1, explanation: 'Declarative partitioning (introduced in PostgreSQL 10) lets you define a partitioning strategy (RANGE, LIST, HASH) on the parent table. PostgreSQL automatically routes INSERT operations to the correct partition and can prune irrelevant partitions during queries.', codeSnippet: "CREATE TABLE orders (\n  id BIGSERIAL,\n  order_date DATE NOT NULL,\n  total NUMERIC(10,2)\n) PARTITION BY RANGE (order_date);\n\nCREATE TABLE orders_2024_q1 PARTITION OF orders\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');\nCREATE TABLE orders_2024_q2 PARTITION OF orders\n  FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');", tags: ['schema-design', 'partitioning', 'declarative'] },
  { id: 'pg-schema-design-l3-005', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'Which partitioning strategy divides data based on ranges of column values?', options: ['LIST partitioning', 'HASH partitioning', 'RANGE partitioning — rows are routed to partitions based on value ranges', 'ROUND ROBIN partitioning'], correctAnswer: 2, explanation: 'RANGE partitioning assigns rows to partitions based on whether the partition key falls within a specified range. It is ideal for time-series data where you partition by date or timestamp.', codeSnippet: "CREATE TABLE measurements (\n  id BIGSERIAL,\n  recorded_at TIMESTAMPTZ NOT NULL,\n  value DOUBLE PRECISION\n) PARTITION BY RANGE (recorded_at);\n\nCREATE TABLE measurements_2024_01 PARTITION OF measurements\n  FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');", tags: ['schema-design', 'partitioning', 'range'] },
  { id: 'pg-schema-design-l3-006', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What does LIST partitioning do?', options: ['Creates a list of all rows', 'Routes rows to partitions based on exact matches of discrete values in the partition key', 'Lists all available partitions', 'Sorts rows into an ordered list'], correctAnswer: 1, explanation: 'LIST partitioning assigns rows to partitions based on specific enumerated values. It is ideal when the partition key has a limited set of known values, such as country codes, statuses, or categories.', codeSnippet: "CREATE TABLE orders (\n  id BIGSERIAL,\n  region TEXT NOT NULL,\n  total NUMERIC(10,2)\n) PARTITION BY LIST (region);\n\nCREATE TABLE orders_us PARTITION OF orders FOR VALUES IN ('US');\nCREATE TABLE orders_eu PARTITION OF orders FOR VALUES IN ('DE','FR','IT','ES');\nCREATE TABLE orders_asia PARTITION OF orders FOR VALUES IN ('JP','KR','CN');", tags: ['schema-design', 'partitioning', 'list'] },
  { id: 'pg-schema-design-l3-007', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What does HASH partitioning achieve?', options: ['Encrypts the partition key', 'Distributes rows evenly across partitions using a hash function on the partition key', 'Sorts partitions alphabetically', 'Compresses partition data'], correctAnswer: 1, explanation: 'HASH partitioning applies a hash function to the partition key and assigns rows to partitions based on the modulus. This provides roughly even distribution when there is no natural range or list to partition by.', codeSnippet: "CREATE TABLE sessions (\n  id UUID NOT NULL,\n  user_id INT NOT NULL,\n  data JSONB\n) PARTITION BY HASH (id);\n\nCREATE TABLE sessions_p0 PARTITION OF sessions FOR VALUES WITH (MODULUS 4, REMAINDER 0);\nCREATE TABLE sessions_p1 PARTITION OF sessions FOR VALUES WITH (MODULUS 4, REMAINDER 1);\nCREATE TABLE sessions_p2 PARTITION OF sessions FOR VALUES WITH (MODULUS 4, REMAINDER 2);\nCREATE TABLE sessions_p3 PARTITION OF sessions FOR VALUES WITH (MODULUS 4, REMAINDER 3);", tags: ['schema-design', 'partitioning', 'hash'] },
  { id: 'pg-schema-design-l3-008', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What is partition pruning?', options: ['Deleting old partitions', 'An optimization where PostgreSQL skips scanning partitions that cannot contain matching rows based on query predicates', 'Merging small partitions', 'Compressing partition data'], correctAnswer: 1, explanation: 'Partition pruning is a query optimization where the planner examines WHERE clause conditions against partition boundaries and excludes partitions that cannot contain relevant data. This dramatically speeds up queries on large partitioned tables.', codeSnippet: "-- With orders partitioned by RANGE(order_date):\nEXPLAIN SELECT * FROM orders\nWHERE order_date >= '2024-03-01' AND order_date < '2024-04-01';\n-- Output shows only orders_2024_q1 is scanned;\n-- other partitions are pruned", tags: ['schema-design', 'partitioning', 'pruning'] },
  { id: 'pg-schema-design-l3-009', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is an exclusion constraint in PostgreSQL?', options: ['A constraint that excludes NULL values', 'A constraint ensuring that for any two rows, a comparison of specified column pairs using specified operators does not all evaluate to TRUE', 'A constraint that excludes duplicate rows', 'A constraint limiting table size'], correctAnswer: 1, explanation: 'Exclusion constraints generalize UNIQUE constraints. They guarantee that if any two rows are compared on the specified columns using the specified operators, at least one comparison returns FALSE. They are commonly used with range types to prevent overlaps.', codeSnippet: "CREATE EXTENSION IF NOT EXISTS btree_gist;\n\nCREATE TABLE reservations (\n  room_id INT,\n  during TSTZRANGE,\n  EXCLUDE USING gist (room_id WITH =, during WITH &&)\n);\n-- Prevents overlapping reservations for the same room", tags: ['schema-design', 'exclusion-constraint', 'ranges'] },
  { id: 'pg-schema-design-l3-010', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What does a CHECK constraint with a function call do?', options: ['It is not allowed', 'It validates data against an arbitrary expression that can include function calls, as long as the function is IMMUTABLE', 'It automatically transforms the data', 'It logs a warning'], correctAnswer: 1, explanation: 'CHECK constraints can use any expression that evaluates to a boolean, including IMMUTABLE function calls. The function must be IMMUTABLE because the constraint is evaluated at insert/update time and must produce consistent results.', codeSnippet: "CREATE OR REPLACE FUNCTION is_valid_email(email TEXT)\nRETURNS BOOLEAN AS $$\n  SELECT email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$';\n$$ LANGUAGE sql IMMUTABLE;\n\nCREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  email TEXT NOT NULL CHECK (is_valid_email(email))\n);", tags: ['schema-design', 'check-constraint', 'functions'] },
  { id: 'pg-schema-design-l3-011', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is a deferred constraint?', options: ['A constraint that is never checked', 'A constraint whose validation is postponed until COMMIT time rather than being checked on each statement', 'A constraint added later via ALTER TABLE', 'A soft constraint that only warns'], correctAnswer: 1, explanation: 'DEFERRABLE constraints can be set to DEFERRED, meaning they are checked at transaction commit time rather than after each individual statement. This allows temporarily violating constraints within a transaction as long as everything is consistent by commit.', codeSnippet: "CREATE TABLE nodes (\n  id INT PRIMARY KEY,\n  parent_id INT REFERENCES nodes(id)\n    DEFERRABLE INITIALLY DEFERRED\n);\n\nBEGIN;\n-- Insert child before parent — allowed because check deferred to COMMIT\nINSERT INTO nodes VALUES (2, 1);\nINSERT INTO nodes VALUES (1, NULL);\nCOMMIT;  -- constraint checked here", tags: ['schema-design', 'deferred-constraints', 'transactions'] },
  { id: 'pg-schema-design-l3-012', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'What is a generated column in PostgreSQL?', options: ['A column with a DEFAULT value', 'A column whose value is always computed from an expression on other columns in the same row', 'A column with auto-increment', 'A column created by a trigger'], correctAnswer: 1, explanation: 'Generated columns (PostgreSQL 12+) are computed automatically from other columns. PostgreSQL supports STORED generated columns, which are computed on write and physically stored. VIRTUAL generated columns are not yet supported.', codeSnippet: "CREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  price NUMERIC(10,2) NOT NULL,\n  tax_rate NUMERIC(4,3) NOT NULL DEFAULT 0.19,\n  total_price NUMERIC(10,2) GENERATED ALWAYS AS (price * (1 + tax_rate)) STORED\n);\n\nINSERT INTO products (price) VALUES (100.00);\nSELECT total_price FROM products;  -- 119.00", tags: ['schema-design', 'generated-columns', 'computed'] },
  { id: 'pg-schema-design-l3-013', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can a generated column reference other generated columns?', options: ['Yes, in any order', 'No — a generated column can only reference base (non-generated) columns of the same table', 'Only if they are in order', 'Only with VIRTUAL generated columns'], correctAnswer: 1, explanation: 'PostgreSQL requires generated column expressions to reference only non-generated columns. This prevents circular dependencies and ensures the computation order is well-defined.', codeSnippet: "-- This will FAIL:\nCREATE TABLE bad_example (\n  a INT,\n  b INT GENERATED ALWAYS AS (a * 2) STORED,\n  c INT GENERATED ALWAYS AS (b + 1) STORED  -- ERROR: cannot reference generated column\n);", tags: ['schema-design', 'generated-columns', 'restrictions'] },
  { id: 'pg-schema-design-l3-014', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Inheritance', question: 'What is table inheritance in PostgreSQL?', options: ['Copying table structure with CREATE TABLE LIKE', 'A feature where a child table inherits all columns and constraints from a parent table and can add its own', 'Foreign key relationships', 'Creating views on top of tables'], correctAnswer: 1, explanation: 'PostgreSQL table inheritance allows a child table to inherit all columns from a parent. Queries on the parent also return rows from child tables by default. This is a PostgreSQL-specific feature not in the SQL standard.', codeSnippet: "CREATE TABLE vehicles (\n  id SERIAL PRIMARY KEY,\n  make TEXT NOT NULL,\n  model TEXT NOT NULL,\n  year INT\n);\n\nCREATE TABLE cars (\n  num_doors INT DEFAULT 4\n) INHERITS (vehicles);\n\n-- Query the parent to see all vehicles including cars:\nSELECT * FROM vehicles;  -- includes car rows\nSELECT * FROM ONLY vehicles;  -- excludes inherited rows", tags: ['schema-design', 'inheritance', 'object-relational'] },
  { id: 'pg-schema-design-l3-015', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Inheritance', question: 'What does the ONLY keyword do when querying an inherited table?', options: ['Selects only one row', 'Restricts the query to only the specified table, excluding rows from child tables', 'Forces a sequential scan', 'Locks the table exclusively'], correctAnswer: 1, explanation: 'By default, SELECT on a parent table returns rows from the parent and all child tables. The ONLY keyword limits the query to just the specified table, excluding inherited child table rows.', codeSnippet: "-- Returns rows from vehicles AND all child tables (cars, trucks, etc.):\nSELECT * FROM vehicles;\n\n-- Returns rows ONLY from the vehicles table itself:\nSELECT * FROM ONLY vehicles;", tags: ['schema-design', 'inheritance', 'only-keyword'] },
  { id: 'pg-schema-design-l3-016', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What does ON DELETE SET DEFAULT do in a foreign key constraint?', options: ['Deletes the default value', 'When the referenced row is deleted, sets the foreign key column to its DEFAULT value', 'Sets the parent to default', 'Prevents deletion of the default row'], correctAnswer: 1, explanation: 'ON DELETE SET DEFAULT is a referential action that sets the foreign key column to its DEFAULT value when the referenced parent row is deleted. The default value must satisfy the foreign key constraint (i.e., reference an existing row or be NULL).', codeSnippet: "CREATE TABLE categories (\n  id INT PRIMARY KEY,\n  name TEXT\n);\nINSERT INTO categories VALUES (0, 'Uncategorized'), (1, 'Electronics');\n\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  category_id INT DEFAULT 0 REFERENCES categories(id)\n    ON DELETE SET DEFAULT\n);\n-- Deleting category 1 sets products to category 0", tags: ['schema-design', 'foreign-key', 'on-delete-set-default'] },
  { id: 'pg-schema-design-l3-017', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What does ON UPDATE CASCADE do?', options: ['Deletes the child row when the parent is updated', 'When the referenced primary key value changes, automatically updates all foreign key columns that reference it', 'Prevents updates to the parent table', 'Cascades the update to all tables in the schema'], correctAnswer: 1, explanation: 'ON UPDATE CASCADE automatically propagates changes to the referenced column value to all rows that reference it. If a primary key value is updated, all foreign key columns pointing to it are updated to match.', codeSnippet: "CREATE TABLE departments (\n  code CHAR(4) PRIMARY KEY,\n  name TEXT\n);\n\nCREATE TABLE employees (\n  id SERIAL PRIMARY KEY,\n  dept_code CHAR(4) REFERENCES departments(code)\n    ON UPDATE CASCADE\n);\n\n-- Changing department code automatically updates all employees:\nUPDATE departments SET code = 'ENGR' WHERE code = 'ENG';", tags: ['schema-design', 'foreign-key', 'on-update-cascade'] },
  { id: 'pg-schema-design-l3-018', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Schemas', question: 'What is the purpose of PostgreSQL schemas (namespaces)?', options: ['To encrypt data', 'To organize database objects into logical groups, allowing multiple objects with the same name in different schemas', 'To create backup copies', 'To define data types'], correctAnswer: 1, explanation: 'Schemas provide a namespace mechanism within a database. They allow you to organize tables, views, functions, and other objects into logical groups, prevent naming conflicts, and manage access control at a higher level.', codeSnippet: "CREATE SCHEMA sales;\nCREATE SCHEMA inventory;\n\n-- Same table name in different schemas:\nCREATE TABLE sales.orders (id SERIAL PRIMARY KEY, total NUMERIC);\nCREATE TABLE inventory.orders (id SERIAL PRIMARY KEY, warehouse_id INT);\n\n-- Set search path to control default schema:\nSET search_path TO sales, public;", tags: ['schema-design', 'schemas', 'namespaces'] },
  { id: 'pg-schema-design-l3-019', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Schemas', question: 'What is the search_path in PostgreSQL?', options: ['The filesystem path to the database', 'An ordered list of schemas that PostgreSQL searches when resolving unqualified object names', 'The path for full-text search', 'The index scan path'], correctAnswer: 1, explanation: 'search_path is a configuration parameter listing schemas to search when a table or other object is referenced without a schema qualifier. The first schema in the path is also the default schema for CREATE operations.', codeSnippet: "-- View current search_path:\nSHOW search_path;  -- typically: \"$user\", public\n\n-- Set a custom search_path:\nSET search_path TO myapp, shared, public;\n\n-- Now 'users' resolves to the first match in myapp, shared, or public:\nSELECT * FROM users;", tags: ['schema-design', 'search-path', 'schemas'] },
  { id: 'pg-schema-design-l3-020', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Domain Types', question: 'What is a DOMAIN in PostgreSQL?', options: ['A database hostname', 'A user-defined data type based on an existing type with optional constraints, providing reusable type definitions', 'A security boundary', 'A group of related tables'], correctAnswer: 1, explanation: 'A DOMAIN is a named data type based on an underlying type with optional CHECK constraints. Domains provide reusable, centrally-managed type definitions that ensure consistent validation across all columns using that domain.', codeSnippet: "CREATE DOMAIN email_address AS TEXT\n  CHECK (VALUE ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$');\n\nCREATE DOMAIN positive_int AS INTEGER\n  CHECK (VALUE > 0);\n\nCREATE TABLE users (\n  id positive_int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  email email_address NOT NULL UNIQUE\n);", tags: ['schema-design', 'domain', 'custom-types'] },
  { id: 'pg-schema-design-l3-021', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Composite Types', question: 'What is a composite type in PostgreSQL?', options: ['A column with multiple data types', 'A named type that groups multiple fields into a structure, similar to a row type', 'A type that combines TEXT and INTEGER', 'A JSON-like data structure'], correctAnswer: 1, explanation: 'Composite types define a structure of named fields with data types. Every table automatically defines a composite type of the same name. You can also create standalone composite types for use as column types or function parameters.', codeSnippet: "CREATE TYPE address AS (\n  street TEXT,\n  city TEXT,\n  state CHAR(2),\n  zip VARCHAR(10)\n);\n\nCREATE TABLE customers (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  home_address address,\n  work_address address\n);\n\nSELECT (home_address).city FROM customers;", tags: ['schema-design', 'composite-types', 'custom-types'] },
  { id: 'pg-schema-design-l3-022', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Enum Types', question: 'What are the trade-offs of using ENUM types in PostgreSQL?', options: ['ENUMs are always better than lookup tables', 'ENUMs enforce valid values and are compact, but adding or removing values requires ALTER TYPE and removing values is not directly supported', 'ENUMs are slower than text columns', 'ENUMs cannot be used in WHERE clauses'], correctAnswer: 1, explanation: 'ENUM types provide type safety and compact storage (4 bytes). Adding new values is straightforward with ALTER TYPE ADD VALUE, but removing or reordering values is not directly supported, requiring a type recreation. For frequently changing value sets, a lookup table with a foreign key may be more flexible.', codeSnippet: "CREATE TYPE order_status AS ENUM ('pending', 'processing', 'shipped', 'delivered');\n\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  status order_status NOT NULL DEFAULT 'pending'\n);\n\n-- Adding a new value:\nALTER TYPE order_status ADD VALUE 'cancelled' AFTER 'delivered';", tags: ['schema-design', 'enum', 'trade-offs'] },
  { id: 'pg-schema-design-l3-023', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is a surrogate key?', options: ['A foreign key', 'An artificial key with no business meaning, generated by the system (e.g., SERIAL, UUID) to serve as primary key', 'A key that replaces another key temporarily', 'A composite key'], correctAnswer: 1, explanation: 'A surrogate key is a system-generated identifier with no inherent business meaning. Surrogate keys provide stable references (unaffected by business data changes) and simple joins (single column). Common types include auto-incrementing integers and UUIDs.', codeSnippet: "-- Surrogate key approach:\nCREATE TABLE employees (\n  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  ssn VARCHAR(11) UNIQUE NOT NULL,  -- natural key as unique constraint\n  name TEXT NOT NULL\n);", tags: ['schema-design', 'surrogate-key', 'primary-key'] },
  { id: 'pg-schema-design-l3-024', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is the advantage of a natural key over a surrogate key?', options: ['Natural keys are always faster', 'Natural keys carry business meaning, can eliminate joins for lookups, and enforce uniqueness of real-world identifiers inherently', 'Natural keys use less storage', 'There is no advantage'], correctAnswer: 1, explanation: 'Natural keys (like ISBN, email, SSN) carry inherent meaning, can serve as both identifier and searchable value (eliminating joins), and guarantee real-world uniqueness. However, they can change, may be composite, and can leak sensitive data.', codeSnippet: "-- Natural key: ISBN already uniquely identifies books\nCREATE TABLE books (\n  isbn CHAR(13) PRIMARY KEY,  -- natural key\n  title TEXT NOT NULL,\n  author TEXT NOT NULL\n);\n\n-- No join needed to look up by ISBN:\nSELECT * FROM books WHERE isbn = '9780134685991';", tags: ['schema-design', 'natural-key', 'primary-key'] },
  { id: 'pg-schema-design-l3-025', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'Can partitioned tables have indexes?', options: ['No, partitions cannot be indexed', 'Yes — you create the index on the parent and PostgreSQL automatically creates matching indexes on all existing and future partitions', 'Only on individual partitions', 'Only unique indexes'], correctAnswer: 1, explanation: 'Creating an index on a partitioned parent table automatically creates corresponding indexes on all existing partitions and on any new partitions added later. You can also create indexes on individual partitions independently.', codeSnippet: "CREATE TABLE logs (\n  id BIGSERIAL,\n  created_at TIMESTAMPTZ NOT NULL,\n  message TEXT\n) PARTITION BY RANGE (created_at);\n\n-- Index on parent applies to all partitions:\nCREATE INDEX idx_logs_created ON logs (created_at);\n\n-- Each new partition automatically gets this index:\nCREATE TABLE logs_2024_01 PARTITION OF logs\n  FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');", tags: ['schema-design', 'partitioning', 'indexes'] },
  { id: 'pg-schema-design-l3-026', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What is a default partition?', options: ['The first partition created', 'A partition that catches all rows not matching any other partition definition', 'The partition with the most rows', 'A partition that stores NULL values'], correctAnswer: 1, explanation: 'A DEFAULT partition receives any rows whose partition key value does not match the bounds of any other partition. This prevents INSERT failures when data does not fit existing partitions, but should be monitored to avoid becoming a catch-all.', codeSnippet: "CREATE TABLE events (\n  id BIGSERIAL,\n  event_type TEXT NOT NULL,\n  payload JSONB\n) PARTITION BY LIST (event_type);\n\nCREATE TABLE events_click PARTITION OF events FOR VALUES IN ('click');\nCREATE TABLE events_view PARTITION OF events FOR VALUES IN ('view');\nCREATE TABLE events_other PARTITION OF events DEFAULT;\n\n-- Unknown event types go to events_other:\nINSERT INTO events (event_type, payload) VALUES ('scroll', '{}');", tags: ['schema-design', 'partitioning', 'default-partition'] },
  { id: 'pg-schema-design-l3-027', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'How do you detach a partition without blocking queries?', options: ['DROP the partition', 'Use ALTER TABLE ... DETACH PARTITION ... CONCURRENTLY to detach without holding an ACCESS EXCLUSIVE lock', 'You cannot detach without blocking', 'Use TRUNCATE on the partition'], correctAnswer: 1, explanation: 'DETACH PARTITION CONCURRENTLY (PostgreSQL 14+) releases the partition from the parent without taking an ACCESS EXCLUSIVE lock on the parent, allowing other queries to continue. The detached table remains as a standalone table.', codeSnippet: "-- Detach old partition without blocking queries on the parent:\nALTER TABLE orders DETACH PARTITION orders_2022_q1 CONCURRENTLY;\n\n-- The detached table still exists as a standalone table:\nSELECT count(*) FROM orders_2022_q1;  -- still accessible\n\n-- Now you can archive or drop it:\n-- DROP TABLE orders_2022_q1;", tags: ['schema-design', 'partitioning', 'detach-concurrently'] },
  { id: 'pg-schema-design-l3-028', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is a multi-column (composite) CHECK constraint?', options: ['A CHECK on each column separately', 'A single CHECK constraint that validates a condition involving multiple columns in the same row', 'A CHECK across multiple tables', 'A CHECK that runs multiple times'], correctAnswer: 1, explanation: 'A composite CHECK constraint references multiple columns and validates a condition that involves relationships between them. It is defined at the table level rather than the column level.', codeSnippet: "CREATE TABLE events (\n  id SERIAL PRIMARY KEY,\n  start_time TIMESTAMPTZ NOT NULL,\n  end_time TIMESTAMPTZ NOT NULL,\n  CONSTRAINT valid_time_range CHECK (end_time > start_time)\n);\n\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  price NUMERIC NOT NULL,\n  sale_price NUMERIC,\n  CONSTRAINT valid_sale CHECK (sale_price IS NULL OR sale_price < price)\n);", tags: ['schema-design', 'check-constraint', 'multi-column'] },
  { id: 'pg-schema-design-l3-029', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you add a NOT NULL constraint to an existing column without long locks?', options: ['ALTER TABLE ... SET NOT NULL always requires a full table scan', 'Add a CHECK (column IS NOT NULL) NOT VALID, validate it separately, then add SET NOT NULL which skips the scan if the CHECK exists', 'You cannot add NOT NULL to existing columns', 'Use CREATE INDEX CONCURRENTLY first'], correctAnswer: 1, explanation: 'In PostgreSQL 12+, SET NOT NULL can skip the full table scan if a valid CHECK (col IS NOT NULL) constraint already exists. You can add the CHECK as NOT VALID (instant), then VALIDATE CONSTRAINT (ShareUpdateExclusiveLock), then SET NOT NULL (instant).', codeSnippet: "-- Step 1: Add CHECK NOT VALID (instant, no scan)\nALTER TABLE users ADD CONSTRAINT users_email_nn\n  CHECK (email IS NOT NULL) NOT VALID;\n\n-- Step 2: Validate (scans table but allows concurrent DML)\nALTER TABLE users VALIDATE CONSTRAINT users_email_nn;\n\n-- Step 3: Add NOT NULL (instant, reuses validated CHECK)\nALTER TABLE users ALTER COLUMN email SET NOT NULL;\n\n-- Step 4: Drop the now-redundant CHECK\nALTER TABLE users DROP CONSTRAINT users_email_nn;", tags: ['schema-design', 'not-null', 'zero-downtime'] },
  { id: 'pg-schema-design-l3-030', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What happens when you have a foreign key without an index on the referencing column?', options: ['PostgreSQL automatically creates the index', 'The foreign key still works but DELETE/UPDATE on the parent table may be very slow due to sequential scans on the child table', 'An error is raised', 'The foreign key is ignored'], correctAnswer: 1, explanation: 'PostgreSQL does NOT automatically index foreign key columns. Without an index, any DELETE or UPDATE on the parent table causes a sequential scan of the child table to check for referencing rows. This is a common performance pitfall.', codeSnippet: "CREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  customer_id INT REFERENCES customers(id)\n);\n-- PostgreSQL does NOT create an index on customer_id!\n\n-- This DELETE scans ALL orders to find references:\nDELETE FROM customers WHERE id = 42;  -- slow without index\n\n-- Fix: always index foreign key columns\nCREATE INDEX idx_orders_customer ON orders (customer_id);", tags: ['schema-design', 'foreign-key', 'index', 'performance'] },
  { id: 'pg-schema-design-l3-031', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Fourth Normal Form (4NF)?', options: ['Same as BCNF', 'A form that eliminates multi-valued dependencies by ensuring no table has more than one independent multi-valued fact about an entity', 'A form requiring all columns to be indexed', 'A form that eliminates all NULLs'], correctAnswer: 1, explanation: '4NF eliminates non-trivial multi-valued dependencies. If an entity has two or more independent multi-valued facts, they should be in separate tables. For example, an employee having multiple skills AND multiple hobbies should store them in two separate junction tables.', codeSnippet: "-- Violation of 4NF: two independent multi-valued facts\nCREATE TABLE emp_skills_hobbies (\n  emp_id INT, skill TEXT, hobby TEXT\n);\n-- Results in cartesian product of skills × hobbies\n\n-- 4NF fix: separate tables\nCREATE TABLE emp_skills (emp_id INT, skill TEXT, PRIMARY KEY (emp_id, skill));\nCREATE TABLE emp_hobbies (emp_id INT, hobby TEXT, PRIMARY KEY (emp_id, hobby));", tags: ['schema-design', 'normalization', '4nf'] },
  { id: 'pg-schema-design-l3-032', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Schemas', question: 'How do you set a default schema for a specific role?', options: ['ALTER ROLE ... SET SCHEMA', 'ALTER ROLE ... SET search_path TO desired_schema — this sets the default search path for all sessions by that role', 'CREATE SCHEMA ... AUTHORIZATION role', 'GRANT USAGE ON SCHEMA'], correctAnswer: 1, explanation: 'ALTER ROLE ... SET search_path permanently sets the search_path for that role. Every session authenticated as that role will use the specified search_path unless overridden at the session level.', codeSnippet: "-- Set default schema for the app_user role:\nALTER ROLE app_user SET search_path TO myapp, public;\n\n-- Now when app_user connects:\n-- SELECT * FROM users;  =>  searches myapp.users first, then public.users\n\n-- Override per session if needed:\nSET search_path TO other_schema, public;", tags: ['schema-design', 'schemas', 'search-path', 'roles'] },
  { id: 'pg-schema-design-l3-033', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Domain Types', question: 'How do you modify the constraint on an existing DOMAIN?', options: ['ALTER DOMAIN ... MODIFY CONSTRAINT', 'Use ALTER DOMAIN ... DROP CONSTRAINT and ALTER DOMAIN ... ADD CONSTRAINT to replace the constraint', 'DROP and recreate the domain', 'You cannot modify domain constraints'], correctAnswer: 1, explanation: 'You can drop an existing constraint from a domain with ALTER DOMAIN ... DROP CONSTRAINT and add a new one with ALTER DOMAIN ... ADD CONSTRAINT. Adding NOT VALID lets you defer validation of existing data.', codeSnippet: "CREATE DOMAIN percentage AS NUMERIC CHECK (VALUE >= 0 AND VALUE <= 100);\n\n-- Relax the constraint to allow values up to 200:\nALTER DOMAIN percentage DROP CONSTRAINT percentage_check;\nALTER DOMAIN percentage ADD CONSTRAINT percentage_check\n  CHECK (VALUE >= 0 AND VALUE <= 200);", tags: ['schema-design', 'domain', 'alter-domain'] },
  { id: 'pg-schema-design-l3-034', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can you create an index on a generated column?', options: ['No, generated columns cannot be indexed', 'Yes — STORED generated columns can be indexed just like regular columns, enabling efficient queries on computed values', 'Only partial indexes', 'Only expression indexes'], correctAnswer: 1, explanation: 'Since STORED generated columns are physically stored on disk, they can be indexed like any regular column. This allows efficient lookups and sorting on computed values without expression indexes.', codeSnippet: "CREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  quantity INT NOT NULL,\n  unit_price NUMERIC(10,2) NOT NULL,\n  total NUMERIC(10,2) GENERATED ALWAYS AS (quantity * unit_price) STORED\n);\n\n-- Index on the generated column:\nCREATE INDEX idx_orders_total ON orders (total);", tags: ['schema-design', 'generated-columns', 'indexes'] },
  { id: 'pg-schema-design-l3-035', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'Can you have multi-level (sub-partitioned) tables in PostgreSQL?', options: ['No, only one level of partitioning', 'Yes — each partition can itself be partitioned using a different partitioning strategy', 'Only with RANGE partitioning', 'Only up to two levels'], correctAnswer: 1, explanation: 'PostgreSQL supports sub-partitioning where a partition is itself a partitioned table. For example, you can RANGE-partition by date and then LIST-partition each date partition by region.', codeSnippet: "CREATE TABLE sales (\n  id BIGSERIAL, region TEXT, sale_date DATE, amount NUMERIC\n) PARTITION BY RANGE (sale_date);\n\n-- Q1 partition, sub-partitioned by region:\nCREATE TABLE sales_2024_q1 PARTITION OF sales\n  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01')\n  PARTITION BY LIST (region);\n\nCREATE TABLE sales_2024_q1_us PARTITION OF sales_2024_q1\n  FOR VALUES IN ('US');\nCREATE TABLE sales_2024_q1_eu PARTITION OF sales_2024_q1\n  FOR VALUES IN ('EU');", tags: ['schema-design', 'partitioning', 'sub-partitioning'] },
  { id: 'pg-schema-design-l3-036', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is the NOT VALID option when adding a constraint?', options: ['Creates an invalid constraint that is never checked', 'Adds the constraint without validating existing rows — only new/updated rows are checked — and the constraint can be validated later', 'Creates a warning-only constraint', 'Adds the constraint temporarily'], correctAnswer: 1, explanation: 'NOT VALID skips the scan of existing data when adding a CHECK or foreign key constraint. The constraint applies only to future INSERT/UPDATE operations. You can later run ALTER TABLE ... VALIDATE CONSTRAINT to verify existing rows with a less restrictive lock.', codeSnippet: "-- Add constraint without scanning existing data (fast):\nALTER TABLE orders ADD CONSTRAINT positive_total\n  CHECK (total > 0) NOT VALID;\n\n-- New inserts are validated immediately:\nINSERT INTO orders (total) VALUES (-5);  -- ERROR\n\n-- Validate existing data later (lower lock level):\nALTER TABLE orders VALIDATE CONSTRAINT positive_total;", tags: ['schema-design', 'not-valid', 'constraints', 'zero-downtime'] },
  { id: 'pg-schema-design-l3-037', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Inheritance', question: 'What are the limitations of PostgreSQL table inheritance?', options: ['No limitations exist', 'Unique constraints and foreign keys on the parent do not span child tables, and indexes are not automatically inherited', 'Inheritance prevents adding columns to child tables', 'Child tables cannot have their own indexes'], correctAnswer: 1, explanation: 'Table inheritance has significant limitations: UNIQUE and PRIMARY KEY constraints are per-table (not enforced across the hierarchy), foreign keys cannot reference the parent to include child rows, and indexes on the parent do not automatically cover child tables. Declarative partitioning addresses some of these issues.', tags: ['schema-design', 'inheritance', 'limitations'] },
  { id: 'pg-schema-design-l3-038', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is a junction (bridge/join) table?', options: ['A temporary table for joins', 'A table that implements a many-to-many relationship by holding foreign keys to both related tables', 'A table that joins two databases', 'A view that combines multiple tables'], correctAnswer: 1, explanation: 'A junction table resolves a many-to-many relationship between two tables. It contains foreign keys referencing both related tables, typically forming a composite primary key, and may include additional attributes about the relationship.', codeSnippet: "CREATE TABLE students (id SERIAL PRIMARY KEY, name TEXT NOT NULL);\nCREATE TABLE courses (id SERIAL PRIMARY KEY, title TEXT NOT NULL);\n\n-- Junction table for many-to-many:\nCREATE TABLE enrollments (\n  student_id INT REFERENCES students(id),\n  course_id INT REFERENCES courses(id),\n  enrolled_at TIMESTAMPTZ DEFAULT now(),\n  grade CHAR(2),\n  PRIMARY KEY (student_id, course_id)\n);", tags: ['schema-design', 'junction-table', 'many-to-many'] },
  { id: 'pg-schema-design-l3-039', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the Entity-Attribute-Value (EAV) pattern and when is it appropriate?', options: ['A standard normalization form', 'A pattern where attributes are stored as rows (entity_id, attribute_name, value) — useful for highly dynamic schemas but sacrifices type safety and query simplicity', 'A way to store entities as JSON', 'A pattern for version control'], correctAnswer: 1, explanation: 'EAV stores attributes as rows instead of columns, allowing unlimited dynamic attributes without schema changes. Drawbacks include loss of type safety, complex queries, inability to use constraints per attribute, and poor performance. JSONB columns are often a better modern alternative.', codeSnippet: "-- EAV pattern (generally avoid in PostgreSQL):\nCREATE TABLE entity_attributes (\n  entity_id INT REFERENCES entities(id),\n  attribute_name TEXT NOT NULL,\n  attribute_value TEXT,\n  PRIMARY KEY (entity_id, attribute_name)\n);\n\n-- Better alternative: JSONB column\nCREATE TABLE entities (\n  id SERIAL PRIMARY KEY,\n  type TEXT NOT NULL,\n  attributes JSONB NOT NULL DEFAULT '{}'\n);", tags: ['schema-design', 'eav', 'anti-pattern'] },
  { id: 'pg-schema-design-l3-040', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the polymorphic association anti-pattern?', options: ['Using multiple inheritance', 'Storing a type column and a generic foreign key that can point to different tables, bypassing referential integrity', 'Using ENUM types for associations', 'Having multiple foreign keys in one table'], correctAnswer: 1, explanation: 'Polymorphic associations use a (type, id) pair where type indicates which table the id references. PostgreSQL cannot enforce this with foreign keys, so referential integrity is lost. Better alternatives include separate foreign key columns, table inheritance, or a shared parent table.', codeSnippet: "-- Anti-pattern: polymorphic association (no FK enforcement)\nCREATE TABLE comments (\n  id SERIAL PRIMARY KEY,\n  commentable_type TEXT NOT NULL,  -- 'post' or 'photo'\n  commentable_id INT NOT NULL,    -- references different tables!\n  body TEXT NOT NULL\n);\n\n-- Better: separate nullable FKs\nCREATE TABLE comments (\n  id SERIAL PRIMARY KEY,\n  post_id INT REFERENCES posts(id),\n  photo_id INT REFERENCES photos(id),\n  body TEXT NOT NULL,\n  CHECK (num_nonnulls(post_id, photo_id) = 1)\n);", tags: ['schema-design', 'polymorphic-association', 'anti-pattern'] },
  { id: 'pg-schema-design-l3-041', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'How do you model a self-referencing (hierarchical) relationship?', options: ['Use table inheritance', 'Use a foreign key that references the same table, creating a parent-child relationship within one table', 'Create a separate hierarchy table', 'Use a recursive view only'], correctAnswer: 1, explanation: 'A self-referencing foreign key creates hierarchical structures like org charts, category trees, or threaded comments. The root node typically has NULL for the parent column. Use recursive CTEs to query the hierarchy.', codeSnippet: "CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  parent_id INT REFERENCES categories(id)\n);\n\nINSERT INTO categories (id, name, parent_id) VALUES\n  (1, 'Electronics', NULL),\n  (2, 'Phones', 1),\n  (3, 'Smartphones', 2);\n\n-- Query full hierarchy:\nWITH RECURSIVE tree AS (\n  SELECT id, name, parent_id, 0 AS depth FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.id, c.name, c.parent_id, t.depth + 1\n  FROM categories c JOIN tree t ON c.parent_id = t.id\n)\nSELECT * FROM tree;", tags: ['schema-design', 'self-reference', 'hierarchy'] },
  { id: 'pg-schema-design-l3-042', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What is the primary key restriction on partitioned tables?', options: ['Partitioned tables cannot have primary keys', 'The partition key columns must be included in the primary key (and all unique constraints) of a partitioned table', 'Primary keys must be on the first column', 'Each partition needs a separate primary key definition'], correctAnswer: 1, explanation: 'PostgreSQL requires the partition key to be part of any PRIMARY KEY or UNIQUE constraint on a partitioned table. This is because uniqueness can only be enforced per partition, and including the partition key ensures each partition can independently enforce the constraint.', codeSnippet: "-- This FAILS: partition key (created_at) not in PK\nCREATE TABLE events (\n  id BIGSERIAL,\n  created_at DATE NOT NULL,\n  PRIMARY KEY (id)  -- ERROR!\n) PARTITION BY RANGE (created_at);\n\n-- This WORKS: partition key included in PK\nCREATE TABLE events (\n  id BIGSERIAL,\n  created_at DATE NOT NULL,\n  PRIMARY KEY (id, created_at)\n) PARTITION BY RANGE (created_at);", tags: ['schema-design', 'partitioning', 'primary-key'] },
  { id: 'pg-schema-design-l3-043', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is the difference between table-level and column-level constraints?', options: ['No functional difference', 'Column-level constraints are defined inline with the column and can only reference that column; table-level constraints are defined separately and can reference multiple columns', 'Table-level constraints are faster', 'Column-level constraints are deprecated'], correctAnswer: 1, explanation: 'Column-level constraints are written in the column definition and implicitly reference that column. Table-level constraints are written after all columns and can reference multiple columns (required for composite constraints). Functionally, single-column constraints are identical either way.', codeSnippet: "CREATE TABLE example (\n  -- Column-level constraints:\n  id SERIAL PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE,\n  age INT CHECK (age > 0),\n\n  -- Table-level constraints (can reference multiple columns):\n  start_date DATE,\n  end_date DATE,\n  CONSTRAINT valid_dates CHECK (end_date > start_date),\n  CONSTRAINT unique_email_per_date UNIQUE (email, start_date)\n);", tags: ['schema-design', 'constraints', 'table-level', 'column-level'] },
  { id: 'pg-schema-design-l3-044', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the best practice for storing monetary values in PostgreSQL?', options: ['Use FLOAT or DOUBLE PRECISION', 'Use NUMERIC (or DECIMAL) with explicit precision and scale to avoid floating-point rounding errors', 'Use the MONEY type', 'Store as INTEGER cents'], correctAnswer: 1, explanation: 'NUMERIC/DECIMAL stores exact decimal values without floating-point rounding errors. FLOAT and DOUBLE PRECISION use binary representation that cannot exactly represent many decimal values. The MONEY type is locale-dependent and inflexible. Storing as integer cents is also acceptable.', codeSnippet: "-- Correct: NUMERIC with precision and scale\nCREATE TABLE transactions (\n  id SERIAL PRIMARY KEY,\n  amount NUMERIC(15,2) NOT NULL,  -- up to 15 digits, 2 decimal places\n  currency CHAR(3) NOT NULL DEFAULT 'USD'\n);\n\n-- WRONG: float loses precision\n-- SELECT 0.1::float + 0.2::float = 0.3::float;  -- FALSE!", tags: ['schema-design', 'money', 'numeric', 'precision'] },
  { id: 'pg-schema-design-l3-045', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can a generated column have a DEFAULT value?', options: ['Yes, DEFAULT is used when the expression is NULL', 'No — a generated column cannot have a DEFAULT clause because its value is always computed from the generation expression', 'Only if the expression is nullable', 'Only with VIRTUAL generated columns'], correctAnswer: 1, explanation: 'Generated columns derive their value entirely from the generation expression. Specifying a DEFAULT value would conflict with the GENERATED ALWAYS AS behavior, so PostgreSQL does not allow it.', tags: ['schema-design', 'generated-columns', 'default'] },
  { id: 'pg-schema-design-l3-046', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the purpose of using UUID as a primary key?', options: ['Faster joins than integers', 'UUIDs provide globally unique identifiers without coordination, enabling distributed ID generation and preventing enumeration attacks', 'UUIDs are always faster', 'PostgreSQL recommends UUIDs over serial'], correctAnswer: 1, explanation: 'UUIDs can be generated independently on any node without central coordination, making them ideal for distributed systems and microservices. They also prevent sequential ID enumeration. The trade-off is larger size (16 bytes vs 4/8 bytes for int/bigint) and worse index locality.', codeSnippet: "CREATE EXTENSION IF NOT EXISTS pgcrypto;\n\nCREATE TABLE documents (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  title TEXT NOT NULL,\n  content TEXT\n);\n\n-- Or with the newer built-in function (PG 13+):\nCREATE TABLE files (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  filename TEXT NOT NULL\n);", tags: ['schema-design', 'uuid', 'primary-key', 'distributed'] },
  { id: 'pg-schema-design-l3-047', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is denormalization using materialized views?', options: ['Storing redundant data in base tables', 'Creating pre-computed, physically stored query results that can be refreshed on demand, avoiding redundancy in base tables', 'Creating normal views', 'Dropping constraints for performance'], correctAnswer: 1, explanation: 'Materialized views store the result of a query physically on disk. Base tables remain fully normalized, while the materialized view provides denormalized, pre-joined data for fast reads. Use REFRESH MATERIALIZED VIEW to update the data.', codeSnippet: "-- Base tables are fully normalized\nCREATE MATERIALIZED VIEW order_summary AS\n  SELECT o.id, c.name AS customer_name, o.total,\n         o.created_at, count(oi.id) AS item_count\n  FROM orders o\n  JOIN customers c ON o.customer_id = c.id\n  JOIN order_items oi ON oi.order_id = o.id\n  GROUP BY o.id, c.name, o.total, o.created_at;\n\nCREATE UNIQUE INDEX ON order_summary (id);\nREFRESH MATERIALIZED VIEW CONCURRENTLY order_summary;", tags: ['schema-design', 'materialized-views', 'denormalization'] },
  { id: 'pg-schema-design-l3-048', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What is a composite foreign key?', options: ['A foreign key referencing multiple tables', 'A foreign key consisting of multiple columns that together reference a multi-column primary key or unique constraint in another table', 'A foreign key with multiple actions', 'A foreign key in a composite type'], correctAnswer: 1, explanation: 'A composite foreign key uses multiple columns to reference a multi-column unique or primary key in another table. All referenced columns must match together; they are checked as a tuple, not individually.', codeSnippet: "CREATE TABLE course_sections (\n  course_id INT,\n  section_num INT,\n  instructor TEXT,\n  PRIMARY KEY (course_id, section_num)\n);\n\nCREATE TABLE enrollments (\n  student_id INT REFERENCES students(id),\n  course_id INT,\n  section_num INT,\n  FOREIGN KEY (course_id, section_num)\n    REFERENCES course_sections (course_id, section_num)\n);", tags: ['schema-design', 'composite-foreign-key', 'multi-column'] },
  { id: 'pg-schema-design-l3-049', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the GENERATED BY DEFAULT AS IDENTITY vs GENERATED ALWAYS AS IDENTITY difference?', options: ['No difference', 'GENERATED BY DEFAULT allows manual override of the identity value; GENERATED ALWAYS prevents manual inserts unless OVERRIDING SYSTEM VALUE is specified', 'ALWAYS is for primary keys, DEFAULT is for other columns', 'DEFAULT uses sequences, ALWAYS does not'], correctAnswer: 1, explanation: 'GENERATED ALWAYS prevents manual value specification (enforcing automatic generation), while GENERATED BY DEFAULT allows manual override. ALWAYS is stricter and prevents accidental sequence-value conflicts. Both use sequences internally.', codeSnippet: "CREATE TABLE t1 (\n  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY\n);\nINSERT INTO t1 (id) VALUES (100);  -- ERROR!\nINSERT INTO t1 OVERRIDING SYSTEM VALUE VALUES (100);  -- OK\n\nCREATE TABLE t2 (\n  id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY\n);\nINSERT INTO t2 (id) VALUES (100);  -- OK, manual value accepted", tags: ['schema-design', 'identity', 'generated-always', 'generated-by-default'] },
  { id: 'pg-schema-design-l3-050', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'How do you attach an existing table as a partition?', options: ['ALTER TABLE ... ADD TABLE', 'Use ALTER TABLE parent ATTACH PARTITION child FOR VALUES ... — the child table must match the parent schema and satisfy the partition constraint', 'MERGE TABLE child INTO parent', 'INSERT INTO parent SELECT * FROM child'], correctAnswer: 1, explanation: 'ATTACH PARTITION adds an existing standalone table as a partition of a partitioned table. PostgreSQL validates that all existing rows satisfy the partition constraint (unless you add a matching CHECK constraint beforehand to skip the scan).', codeSnippet: "-- Existing table with data:\nCREATE TABLE orders_2024_q3 (\n  id BIGSERIAL, order_date DATE NOT NULL, total NUMERIC(10,2)\n);\n\n-- Add CHECK to skip validation scan during attach:\nALTER TABLE orders_2024_q3\n  ADD CONSTRAINT partition_check\n  CHECK (order_date >= '2024-07-01' AND order_date < '2024-10-01');\n\n-- Attach as partition (skips scan because CHECK exists):\nALTER TABLE orders ATTACH PARTITION orders_2024_q3\n  FOR VALUES FROM ('2024-07-01') TO ('2024-10-01');", tags: ['schema-design', 'partitioning', 'attach-partition'] },
  { id: 'pg-schema-design-l3-051', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is a temporal table design pattern?', options: ['A table that stores time zones', 'A design where rows have validity periods (valid_from, valid_to) to track how data changes over time, supporting point-in-time queries', 'A temporary table', 'A table with TIMESTAMP columns'], correctAnswer: 1, explanation: 'Temporal tables track the history of data changes by storing validity periods. This enables querying what the data looked like at any point in time. PostgreSQL range types and exclusion constraints are ideal for implementing this pattern.', codeSnippet: "CREATE TABLE product_prices (\n  product_id INT NOT NULL,\n  price NUMERIC(10,2) NOT NULL,\n  valid_during TSTZRANGE NOT NULL,\n  EXCLUDE USING gist (product_id WITH =, valid_during WITH &&)\n);\n\n-- Query the price at a specific time:\nSELECT price FROM product_prices\nWHERE product_id = 42\n  AND valid_during @> '2024-06-15 12:00:00+00'::timestamptz;", tags: ['schema-design', 'temporal', 'history', 'range-types'] },
  { id: 'pg-schema-design-l3-052', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you enforce that exactly one of several nullable foreign keys is set?', options: ['Use multiple CHECK constraints', 'Use a single CHECK constraint with num_nonnulls() to ensure exactly one column is non-NULL', 'This cannot be enforced in SQL', 'Use triggers only'], correctAnswer: 1, explanation: 'The num_nonnulls() function counts how many of its arguments are non-NULL. A CHECK constraint using num_nonnulls() = 1 ensures exactly one foreign key is populated, implementing an exclusive-or relationship pattern.', codeSnippet: "CREATE TABLE notifications (\n  id SERIAL PRIMARY KEY,\n  user_id INT REFERENCES users(id),\n  team_id INT REFERENCES teams(id),\n  org_id INT REFERENCES orgs(id),\n  message TEXT NOT NULL,\n  -- Exactly one recipient type must be set:\n  CONSTRAINT one_recipient CHECK (\n    num_nonnulls(user_id, team_id, org_id) = 1\n  )\n);", tags: ['schema-design', 'constraints', 'exclusive-arc', 'num_nonnulls'] },
  { id: 'pg-schema-design-l3-053', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the adjacency list model for hierarchical data?', options: ['A linked list implementation', 'A pattern where each row stores a reference to its parent, forming a tree structure queried with recursive CTEs', 'A graph database pattern', 'A flat denormalized structure'], correctAnswer: 1, explanation: 'The adjacency list is the simplest hierarchical model: each row has a parent_id column pointing to its parent row. It is easy to maintain but requires recursive queries (WITH RECURSIVE) to traverse the tree. Alternatives include nested sets and materialized paths.', codeSnippet: "CREATE TABLE org_chart (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  manager_id INT REFERENCES org_chart(id)\n);\n\n-- Find all reports (direct and indirect) for a manager:\nWITH RECURSIVE reports AS (\n  SELECT id, name, manager_id FROM org_chart WHERE id = 1\n  UNION ALL\n  SELECT o.id, o.name, o.manager_id\n  FROM org_chart o JOIN reports r ON o.manager_id = r.id\n)\nSELECT * FROM reports;", tags: ['schema-design', 'adjacency-list', 'hierarchy', 'recursive'] },
  { id: 'pg-schema-design-l3-054', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the materialized path pattern for hierarchical data?', options: ['Using materialized views', 'Storing the full path from root to each node as a text column (e.g., "1/3/7/15"), enabling fast subtree queries with LIKE', 'Storing paths to files', 'Using the ltree extension'], correctAnswer: 1, explanation: 'The materialized path stores the ancestry path as a string in each row. Subtree queries use LIKE with a prefix pattern. It is fast for reads but requires updating paths of all descendants when a node moves. PostgreSQL ltree extension provides a specialized type for this pattern.', codeSnippet: "CREATE TABLE categories (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  path TEXT NOT NULL  -- e.g., '1.3.7'\n);\n\nCREATE INDEX idx_categories_path ON categories USING btree (path text_pattern_ops);\n\n-- Find all descendants of category 3:\nSELECT * FROM categories WHERE path LIKE '1.3.%';\n\n-- Better: use ltree extension\n-- CREATE EXTENSION ltree;\n-- path LTREE, then: path <@ '1.3'", tags: ['schema-design', 'materialized-path', 'hierarchy'] },
  { id: 'pg-schema-design-l3-055', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Schemas', question: 'How do you revoke access to the public schema?', options: ['DROP SCHEMA public', 'REVOKE CREATE ON SCHEMA public FROM PUBLIC — this prevents all roles from creating objects in the public schema', 'ALTER SCHEMA public PRIVATE', 'DELETE SCHEMA public'], correctAnswer: 1, explanation: 'By default, all roles can create objects in the public schema. REVOKE CREATE ON SCHEMA public FROM PUBLIC removes this permission. In PostgreSQL 15+, this is the default behavior — CREATE permission on public is no longer granted automatically.', codeSnippet: "-- Revoke create permission on public schema:\nREVOKE CREATE ON SCHEMA public FROM PUBLIC;\n\n-- Also revoke usage if you want to fully lock it down:\nREVOKE ALL ON SCHEMA public FROM PUBLIC;\n\n-- Then grant specific access:\nGRANT USAGE ON SCHEMA public TO app_readonly;\nGRANT CREATE ON SCHEMA public TO app_admin;", tags: ['schema-design', 'schemas', 'security', 'public-schema'] },
  { id: 'pg-schema-design-l3-056', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'When should you use JSONB columns vs normalized tables?', options: ['Always use JSONB', 'JSONB is ideal for variable/sparse attributes, document-like data, or rapid prototyping; normalized tables are better for structured, frequently queried, and relationship-heavy data', 'Always use normalized tables', 'Use JSONB only for configuration'], correctAnswer: 1, explanation: 'JSONB excels for semi-structured data with variable schemas, nested documents, or data from external APIs. Normalized tables are better when you need referential integrity, complex joins, type safety, and when the schema is well-defined. A hybrid approach often works best.', codeSnippet: "-- Hybrid approach: structured core + JSONB for flexible attributes\nCREATE TABLE products (\n  id SERIAL PRIMARY KEY,\n  name TEXT NOT NULL,\n  price NUMERIC(10,2) NOT NULL,\n  category_id INT REFERENCES categories(id),\n  -- Variable attributes stored as JSONB:\n  attributes JSONB NOT NULL DEFAULT '{}'\n);\n\nCREATE INDEX idx_products_attrs ON products USING gin (attributes);", tags: ['schema-design', 'jsonb', 'normalization', 'hybrid'] },
  { id: 'pg-schema-design-l3-057', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What does VALIDATE CONSTRAINT do?', options: ['Creates a new constraint', 'Scans existing rows to verify they satisfy a NOT VALID constraint, then marks the constraint as valid for the query planner', 'Checks constraint syntax', 'Tests a constraint without applying it'], correctAnswer: 1, explanation: 'VALIDATE CONSTRAINT verifies that all existing rows satisfy a previously added NOT VALID constraint. It acquires a SHARE UPDATE EXCLUSIVE lock (allowing concurrent reads and writes) and, once validated, the planner can use the constraint for query optimization.', codeSnippet: "-- Step 1: Add without validating (instant, AccessExclusiveLock briefly)\nALTER TABLE orders ADD CONSTRAINT positive_total\n  CHECK (total > 0) NOT VALID;\n\n-- Step 2: Validate existing data (ShareUpdateExclusiveLock)\nALTER TABLE orders VALIDATE CONSTRAINT positive_total;\n-- Now the planner knows all rows have total > 0", tags: ['schema-design', 'validate-constraint', 'not-valid'] },
  { id: 'pg-schema-design-l3-058', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is a soft delete pattern?', options: ['Using TRUNCATE instead of DELETE', 'Marking rows as deleted with a flag or timestamp instead of physically removing them, preserving data for audit or recovery', 'Deleting rows during off-peak hours', 'Using deferred constraints for deletion'], correctAnswer: 1, explanation: 'Soft delete marks rows as deleted (e.g., deleted_at timestamp) without removing them. This allows undoing deletions and maintaining audit trails. Use partial indexes and views to filter out soft-deleted rows efficiently.', codeSnippet: "CREATE TABLE documents (\n  id SERIAL PRIMARY KEY,\n  title TEXT NOT NULL,\n  content TEXT,\n  deleted_at TIMESTAMPTZ  -- NULL means not deleted\n);\n\n-- Partial index for fast queries on active rows:\nCREATE INDEX idx_documents_active ON documents (id)\n  WHERE deleted_at IS NULL;\n\n-- View for convenience:\nCREATE VIEW active_documents AS\n  SELECT * FROM documents WHERE deleted_at IS NULL;\n\n-- Soft delete:\nUPDATE documents SET deleted_at = now() WHERE id = 42;", tags: ['schema-design', 'soft-delete', 'audit'] },
  { id: 'pg-schema-design-l3-059', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What is the performance impact of foreign key constraints?', options: ['No impact at all', 'Foreign keys add overhead on INSERT, UPDATE, and DELETE because PostgreSQL must check referenced/referencing tables, but this is typically small and worthwhile for data integrity', 'Foreign keys make all queries 10x slower', 'Foreign keys only affect SELECT performance'], correctAnswer: 1, explanation: 'Foreign key checks require lookups on the referenced table during INSERT/UPDATE, and on the referencing table during parent DELETE/UPDATE. With proper indexes on both sides, the overhead is minimal. The data integrity guarantee typically outweighs the small performance cost.', tags: ['schema-design', 'foreign-key', 'performance'] },
  { id: 'pg-schema-design-l3-060', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is a star schema?', options: ['A schema shaped like a star in a diagram', 'A data warehouse design pattern with a central fact table connected to multiple dimension tables, optimized for analytical queries', 'A schema with all tables connected', 'A schema with exactly five tables'], correctAnswer: 1, explanation: 'A star schema has one or more fact tables (containing measures/metrics and foreign keys) surrounded by dimension tables (containing descriptive attributes). It is intentionally denormalized for fast aggregation queries in OLAP/data warehouse scenarios.', codeSnippet: "-- Fact table (center of the star):\nCREATE TABLE sales_fact (\n  id BIGSERIAL PRIMARY KEY,\n  date_key INT REFERENCES dim_date(key),\n  product_key INT REFERENCES dim_product(key),\n  store_key INT REFERENCES dim_store(key),\n  quantity INT NOT NULL,\n  revenue NUMERIC(12,2) NOT NULL\n);\n\n-- Dimension tables (points of the star):\nCREATE TABLE dim_date (key INT PRIMARY KEY, full_date DATE, year INT, quarter INT, month INT);\nCREATE TABLE dim_product (key INT PRIMARY KEY, name TEXT, category TEXT, brand TEXT);\nCREATE TABLE dim_store (key INT PRIMARY KEY, name TEXT, city TEXT, state TEXT);", tags: ['schema-design', 'star-schema', 'data-warehouse'] },
  { id: 'pg-schema-design-l3-061', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'Can you add a partition to a partitioned table while it is being queried?', options: ['No, all queries must be stopped first', 'Yes — adding partitions with CREATE TABLE ... PARTITION OF requires only a brief SHARE UPDATE EXCLUSIVE lock on the parent', 'Only if the parent table is empty', 'Only in maintenance mode'], correctAnswer: 1, explanation: 'Creating a new partition takes a brief lock on the parent table to update partition metadata but does not block concurrent SELECT, INSERT, UPDATE, or DELETE operations for any significant duration. This makes partition management suitable for online systems.', tags: ['schema-design', 'partitioning', 'online-operations'] },
  { id: 'pg-schema-design-l3-062', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'What is the difference between RESTRICT and NO ACTION for foreign key actions?', options: ['They are identical', 'Both prevent deletion of referenced rows, but NO ACTION can be deferred to commit time while RESTRICT always checks immediately', 'RESTRICT is faster', 'NO ACTION ignores the constraint'], correctAnswer: 1, explanation: 'RESTRICT raises an error immediately when trying to delete/update a referenced row. NO ACTION (the default) also raises an error, but when the constraint is DEFERRABLE and deferred, the check happens at COMMIT time. In practice, they behave identically for non-deferred constraints.', codeSnippet: "-- RESTRICT: always checked immediately\nCREATE TABLE orders (\n  customer_id INT REFERENCES customers(id) ON DELETE RESTRICT\n);\n\n-- NO ACTION with DEFERRABLE: checked at commit\nCREATE TABLE orders2 (\n  customer_id INT REFERENCES customers(id)\n    ON DELETE NO ACTION\n    DEFERRABLE INITIALLY DEFERRED\n);", tags: ['schema-design', 'foreign-key', 'restrict-vs-no-action'] },
  { id: 'pg-schema-design-l3-063', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the audit table pattern?', options: ['A table storing financial audits', 'A design where changes to main tables are logged to separate audit tables (typically via triggers) recording who changed what and when', 'A table with read-only access', 'A system catalog table'], correctAnswer: 1, explanation: 'Audit tables record a history of changes (inserts, updates, deletes) to tracked tables. Typically implemented via triggers, they capture the old/new values, the operation type, timestamp, and the user who made the change.', codeSnippet: "CREATE TABLE users_audit (\n  audit_id BIGSERIAL PRIMARY KEY,\n  operation CHAR(1) NOT NULL,  -- I/U/D\n  changed_at TIMESTAMPTZ DEFAULT now(),\n  changed_by TEXT DEFAULT current_user,\n  old_row JSONB,\n  new_row JSONB\n);\n\nCREATE OR REPLACE FUNCTION audit_users() RETURNS trigger AS $$\nBEGIN\n  INSERT INTO users_audit (operation, old_row, new_row)\n  VALUES (LEFT(TG_OP,1), to_jsonb(OLD), to_jsonb(NEW));\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_audit_users\n  AFTER INSERT OR UPDATE OR DELETE ON users\n  FOR EACH ROW EXECUTE FUNCTION audit_users();", tags: ['schema-design', 'audit', 'triggers', 'history'] },
  { id: 'pg-schema-design-l3-064', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'What types of expressions are allowed in generated column definitions?', options: ['Any SQL expression including subqueries', 'Only IMMUTABLE expressions that reference columns of the same table — no subqueries, aggregate functions, or references to other tables', 'Only arithmetic expressions', 'Only function calls'], correctAnswer: 1, explanation: 'Generated column expressions must be IMMUTABLE (deterministic) and can only reference columns of the same table. They cannot contain subqueries, aggregate functions, window functions, or references to other tables. The expression must be stable and deterministic.', tags: ['schema-design', 'generated-columns', 'expressions'] },
  { id: 'pg-schema-design-l3-065', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is CREATE TABLE ... LIKE and when is it useful?', options: ['Creates a view that looks like another table', 'Copies the column definitions (and optionally constraints, defaults, indexes) from an existing table without copying data', 'Creates an alias for a table', 'Creates a foreign table'], correctAnswer: 1, explanation: 'CREATE TABLE ... LIKE copies the structure of an existing table. Options like INCLUDING CONSTRAINTS, INCLUDING DEFAULTS, INCLUDING INDEXES, and INCLUDING ALL control what is copied. It is useful for creating staging tables, archive tables, or templates.', codeSnippet: "-- Copy structure with all attributes:\nCREATE TABLE orders_archive (LIKE orders INCLUDING ALL);\n\n-- Copy only columns and defaults:\nCREATE TABLE orders_staging (\n  LIKE orders INCLUDING DEFAULTS\n);\n\n-- Add extra columns to the copy:\nCREATE TABLE orders_import (\n  LIKE orders INCLUDING DEFAULTS,\n  imported_at TIMESTAMPTZ DEFAULT now()\n);", tags: ['schema-design', 'create-table-like', 'structure-copy'] },
  { id: 'pg-schema-design-l3-066', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'How do you implement a one-to-one relationship in PostgreSQL?', options: ['Use a junction table', 'Use a foreign key with a UNIQUE constraint on the referencing column, ensuring each parent has at most one related child', 'Use table inheritance only', 'One-to-one relationships are not possible'], correctAnswer: 1, explanation: 'A one-to-one relationship is implemented by adding a UNIQUE constraint to the foreign key column. This ensures each value in the referencing table maps to exactly one row in the referenced table. Alternatively, both tables can share the same primary key.', codeSnippet: "-- Option 1: FK with UNIQUE\nCREATE TABLE users (id SERIAL PRIMARY KEY, name TEXT NOT NULL);\nCREATE TABLE user_profiles (\n  id SERIAL PRIMARY KEY,\n  user_id INT UNIQUE NOT NULL REFERENCES users(id),\n  bio TEXT,\n  avatar_url TEXT\n);\n\n-- Option 2: Shared primary key\nCREATE TABLE user_settings (\n  user_id INT PRIMARY KEY REFERENCES users(id),\n  theme TEXT DEFAULT 'light',\n  language TEXT DEFAULT 'en'\n);", tags: ['schema-design', 'one-to-one', 'relationships'] },
  { id: 'pg-schema-design-l3-067', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is First Normal Form (1NF)?', options: ['Tables must have a primary key', 'Each column must contain only atomic (indivisible) values, and each row must be uniquely identifiable — no repeating groups or arrays in columns', 'All columns must be NOT NULL', 'Tables must have fewer than 10 columns'], correctAnswer: 1, explanation: '1NF requires that each column holds a single atomic value (not a list or set), that there are no repeating groups of columns, and that each row is unique. Violations include storing comma-separated values or having columns like phone1, phone2, phone3.', codeSnippet: "-- Violates 1NF: comma-separated values\nCREATE TABLE contacts_bad (\n  id INT PRIMARY KEY,\n  name TEXT,\n  phones TEXT  -- '555-1234,555-5678'\n);\n\n-- 1NF: separate table for multi-valued attribute\nCREATE TABLE contacts (id INT PRIMARY KEY, name TEXT);\nCREATE TABLE contact_phones (\n  contact_id INT REFERENCES contacts(id),\n  phone TEXT NOT NULL,\n  PRIMARY KEY (contact_id, phone)\n);", tags: ['schema-design', 'normalization', '1nf'] },
  { id: 'pg-schema-design-l3-068', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the difference between UNLOGGED and LOGGED tables?', options: ['UNLOGGED tables are not visible to queries', 'UNLOGGED tables skip WAL writes for faster inserts but are not crash-safe — data is lost after a crash and is not replicated', 'UNLOGGED tables have no indexes', 'UNLOGGED tables are temporary'], correctAnswer: 1, explanation: 'UNLOGGED tables do not write WAL (Write-Ahead Log) records, making writes significantly faster. However, they are not crash-safe (truncated after unclean shutdown), not replicated to standbys, and not included in backups taken via pg_basebackup streaming.', codeSnippet: "-- Fast but not crash-safe:\nCREATE UNLOGGED TABLE import_staging (\n  id SERIAL PRIMARY KEY,\n  raw_data JSONB\n);\n\n-- Good for: ETL staging, temp computation, caches\n-- Bad for: anything you cannot afford to lose\n\n-- Convert back to logged if needed:\nALTER TABLE import_staging SET LOGGED;", tags: ['schema-design', 'unlogged', 'performance', 'wal'] },
  { id: 'pg-schema-design-l3-069', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you create a partial unique constraint?', options: ['ALTER UNIQUE ... WHERE', 'Create a unique index with a WHERE clause — PostgreSQL enforces uniqueness only for rows matching the filter condition', 'Use CHECK with UNIQUE', 'Partial unique constraints are not supported'], correctAnswer: 1, explanation: 'PostgreSQL does not support WHERE clauses on UNIQUE constraints directly, but a unique index with a WHERE clause achieves the same effect. This is useful for enforcing uniqueness on a subset of rows, such as "only one active record per user."', codeSnippet: "CREATE TABLE subscriptions (\n  id SERIAL PRIMARY KEY,\n  user_id INT NOT NULL REFERENCES users(id),\n  plan TEXT NOT NULL,\n  active BOOLEAN NOT NULL DEFAULT true\n);\n\n-- Only one active subscription per user:\nCREATE UNIQUE INDEX idx_one_active_sub\n  ON subscriptions (user_id)\n  WHERE active = true;", tags: ['schema-design', 'partial-unique', 'unique-index'] },
  { id: 'pg-schema-design-l3-070', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the multi-tenant schema design approach?', options: ['One database per tenant', 'Using a tenant_id column in every table with Row-Level Security (RLS) policies to isolate tenant data within a shared schema', 'Creating a separate schema per tenant', 'All three are valid approaches'], correctAnswer: 3, explanation: 'The three main multi-tenant approaches are: shared schema with tenant_id column (simplest, scales well), schema-per-tenant (good isolation, moderate overhead), and database-per-tenant (strongest isolation, highest overhead). The best choice depends on isolation requirements, number of tenants, and operational complexity.', codeSnippet: "-- Approach 1: Shared schema with RLS\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  tenant_id INT NOT NULL,\n  total NUMERIC(10,2)\n);\n\nALTER TABLE orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY tenant_isolation ON orders\n  USING (tenant_id = current_setting('app.tenant_id')::int);\n\n-- Set tenant context per session:\nSET app.tenant_id = '42';", tags: ['schema-design', 'multi-tenant', 'rls', 'architecture'] },
  { id: 'pg-schema-design-l3-071', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Schemas', question: 'What is the purpose of CREATE SCHEMA AUTHORIZATION?', options: ['Creates a schema with password protection', 'Creates a schema owned by the specified role, with the schema name defaulting to the role name if not explicitly specified', 'Authorizes users to access all schemas', 'Creates an authorization table in the schema'], correctAnswer: 1, explanation: 'CREATE SCHEMA AUTHORIZATION role_name creates a schema owned by the specified role. If no schema name is given, it defaults to the role name. This is useful for granting each role its own namespace.', codeSnippet: "-- Creates schema named 'app_user' owned by app_user:\nCREATE SCHEMA AUTHORIZATION app_user;\n\n-- Creates schema 'myschema' owned by app_user:\nCREATE SCHEMA myschema AUTHORIZATION app_user;\n\n-- Objects created by app_user default to their schema\n-- when search_path includes \"$user\"", tags: ['schema-design', 'schemas', 'authorization'] },
  { id: 'pg-schema-design-l3-072', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the immutable append-only table pattern?', options: ['A table with no UPDATE permission', 'A design where data is only inserted, never updated or deleted, using triggers or rules to enforce immutability for audit compliance', 'A table that cannot be dropped', 'A table with only INSERT triggers'], correctAnswer: 1, explanation: 'Append-only (immutable) tables only allow INSERTs. Changes are modeled as new rows (with version numbers or timestamps) rather than UPDATEs. This provides a complete audit trail, simplifies replication, and supports event sourcing patterns. Enforced via REVOKE or rules/triggers.', codeSnippet: "CREATE TABLE events (\n  id BIGSERIAL PRIMARY KEY,\n  entity_id INT NOT NULL,\n  event_type TEXT NOT NULL,\n  payload JSONB NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Prevent updates and deletes:\nCREATE RULE no_update AS ON UPDATE TO events DO INSTEAD NOTHING;\nCREATE RULE no_delete AS ON DELETE TO events DO INSTEAD NOTHING;\n\n-- Or use REVOKE:\n-- REVOKE UPDATE, DELETE ON events FROM app_user;", tags: ['schema-design', 'append-only', 'immutable', 'event-sourcing'] },
  { id: 'pg-schema-design-l3-073', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Inheritance', question: 'How does partitioning differ from table inheritance?', options: ['They are the same feature', 'Partitioning enforces that each row belongs to exactly one partition and supports global indexes and unique constraints across partitions; inheritance is more flexible but lacks these guarantees', 'Inheritance is newer than partitioning', 'Partitioning requires triggers'], correctAnswer: 1, explanation: 'Declarative partitioning (PG 10+) automatically routes rows and supports partition pruning, global indexes, and unique constraints including the partition key. Table inheritance does not guarantee row exclusivity, does not route inserts automatically, and unique constraints do not span the hierarchy.', tags: ['schema-design', 'partitioning-vs-inheritance', 'comparison'] },
  { id: 'pg-schema-design-l3-074', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is a lateral column alias in PostgreSQL and how does it affect schema design?', options: ['A column alias that can be referenced by other columns in the same SELECT list', 'PostgreSQL does NOT support lateral column aliases in SELECT lists — you must use subqueries or CTEs to reference computed values', 'A column defined in a LATERAL join', 'An alias for a generated column'], correctAnswer: 1, explanation: 'Unlike some databases (e.g., MySQL), PostgreSQL does not allow referencing a column alias defined earlier in the same SELECT list. You must use a subquery, CTE, or LATERAL join to reference computed values. This matters when designing views and materialized views.', codeSnippet: "-- This FAILS in PostgreSQL:\nSELECT price * quantity AS subtotal,\n       subtotal * 0.1 AS tax;  -- ERROR: column \"subtotal\" does not exist\n\n-- Fix: use a subquery or CTE\nSELECT subtotal, subtotal * 0.1 AS tax\nFROM (\n  SELECT price * quantity AS subtotal FROM order_items\n) sub;", tags: ['schema-design', 'column-alias', 'limitations'] },
  { id: 'pg-schema-design-l3-075', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'Can CHECK constraints reference the current timestamp?', options: ['Yes, CHECK (created_at <= now()) works fine', 'No — CHECK constraints must be IMMUTABLE; functions like now() or CURRENT_TIMESTAMP are not allowed because they return different values at different times', 'Only with TIMESTAMPTZ columns', 'Only in triggers'], correctAnswer: 1, explanation: 'CHECK constraints require immutable expressions. Time-dependent functions like now(), CURRENT_TIMESTAMP, random(), or anything that depends on external state is not permitted. Use triggers or application-level validation for time-dependent checks.', codeSnippet: "-- This FAILS:\nCREATE TABLE events (\n  id SERIAL PRIMARY KEY,\n  scheduled_at TIMESTAMPTZ CHECK (scheduled_at > now())  -- ERROR!\n);\n\n-- Use a trigger instead:\nCREATE FUNCTION check_future_date() RETURNS trigger AS $$\nBEGIN\n  IF NEW.scheduled_at <= now() THEN\n    RAISE EXCEPTION 'scheduled_at must be in the future';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", tags: ['schema-design', 'check-constraint', 'immutable'] },
  { id: 'pg-schema-design-l3-076', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Partitioning', question: 'What happens when you INSERT a row that does not match any partition?', options: ['It goes to the parent table', 'If there is no DEFAULT partition, PostgreSQL raises an error: "no partition of relation ... found for row"', 'It is silently discarded', 'PostgreSQL creates a new partition automatically'], correctAnswer: 1, explanation: 'Without a DEFAULT partition, inserting a row whose partition key does not match any partition boundary causes an error. You can either add a DEFAULT partition (catches unmatched rows) or ensure your application only inserts values within defined ranges.', codeSnippet: "CREATE TABLE logs (\n  id BIGSERIAL, created_at DATE NOT NULL, msg TEXT\n) PARTITION BY RANGE (created_at);\n\nCREATE TABLE logs_2024 PARTITION OF logs\n  FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');\n\n-- This FAILS: no partition for 2025\nINSERT INTO logs (created_at, msg)\nVALUES ('2025-06-15', 'oops');\n-- ERROR: no partition of relation \"logs\" found for row", tags: ['schema-design', 'partitioning', 'insert-error'] },
  { id: 'pg-schema-design-l3-077', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Domain Types', question: 'How does a DOMAIN differ from a composite type?', options: ['They are the same thing', 'A DOMAIN is a single scalar type with constraints; a composite type is a structured type with multiple named fields', 'DOMAINs are faster', 'Composite types support constraints, DOMAINs do not'], correctAnswer: 1, explanation: 'A DOMAIN wraps an existing scalar type (like TEXT or INTEGER) with optional constraints. A composite type defines a new structure with multiple fields, similar to a struct or record. They serve different purposes: DOMAINs for constrained scalars, composite types for structured data.', codeSnippet: "-- DOMAIN: constrained scalar type\nCREATE DOMAIN positive_amount AS NUMERIC(10,2)\n  CHECK (VALUE > 0);\n\n-- Composite type: structured multi-field type\nCREATE TYPE money_value AS (\n  amount NUMERIC(10,2),\n  currency CHAR(3)\n);\n\nCREATE TABLE payments (\n  id SERIAL PRIMARY KEY,\n  total positive_amount NOT NULL,\n  payment money_value NOT NULL\n);", tags: ['schema-design', 'domain', 'composite-type', 'comparison'] },
  { id: 'pg-schema-design-l3-078', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the purpose of tablespaces in schema design?', options: ['To create more disk space', 'To specify physical storage locations for database objects, allowing placement on different disks for performance or capacity management', 'To organize tables by namespace', 'To limit table size'], correctAnswer: 1, explanation: 'Tablespaces define physical locations on disk where PostgreSQL stores database objects. You can place frequently accessed tables/indexes on fast SSDs and archival data on slower, larger disks. The default tablespace is pg_default.', codeSnippet: "-- Create a tablespace on a fast SSD:\nCREATE TABLESPACE fast_ssd LOCATION '/mnt/ssd/pgdata';\n\n-- Create a table on the fast tablespace:\nCREATE TABLE hot_data (\n  id SERIAL PRIMARY KEY,\n  value TEXT\n) TABLESPACE fast_ssd;\n\n-- Move an existing table:\nALTER TABLE archive_data SET TABLESPACE slow_hdd;", tags: ['schema-design', 'tablespaces', 'storage'] },
  { id: 'pg-schema-design-l3-079', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'How do you add a foreign key constraint to a large table without downtime?', options: ['ALTER TABLE ... ADD FOREIGN KEY is always instant', 'Add the foreign key with NOT VALID to avoid scanning existing rows, then validate it separately with VALIDATE CONSTRAINT using a less restrictive lock', 'You cannot add foreign keys to large tables', 'Use CREATE INDEX CONCURRENTLY first'], correctAnswer: 1, explanation: 'Adding a foreign key NOT VALID skips the validation scan of existing rows (acquiring only a brief lock). Then VALIDATE CONSTRAINT checks existing rows with a ShareUpdateExclusiveLock that allows concurrent reads and writes. This two-step process avoids long-held ACCESS EXCLUSIVE locks.', codeSnippet: "-- Step 1: Add FK without validating (brief lock)\nALTER TABLE orders ADD CONSTRAINT fk_customer\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n  NOT VALID;\n\n-- Step 2: Validate (concurrent DML allowed)\nALTER TABLE orders VALIDATE CONSTRAINT fk_customer;", tags: ['schema-design', 'foreign-key', 'not-valid', 'zero-downtime'] },
  { id: 'pg-schema-design-l3-080', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the difference between TEMPORARY and UNLOGGED tables?', options: ['They are the same', 'TEMPORARY tables are session-specific and automatically dropped at session/transaction end; UNLOGGED tables are persistent, visible to all sessions, but skip WAL for performance', 'UNLOGGED tables are session-specific', 'TEMPORARY tables persist across sessions'], correctAnswer: 1, explanation: 'TEMPORARY (TEMP) tables exist only for the current session and are automatically cleaned up. UNLOGGED tables persist across sessions like normal tables but skip WAL writes for performance, at the cost of crash safety.', codeSnippet: "-- Temporary: session-scoped, auto-dropped\nCREATE TEMPORARY TABLE temp_results (\n  id INT, score NUMERIC\n);\n-- Dropped when session ends\n\n-- Unlogged: persistent but no WAL\nCREATE UNLOGGED TABLE cache_table (\n  key TEXT PRIMARY KEY,\n  value JSONB,\n  expires_at TIMESTAMPTZ\n);\n-- Survives session end, lost on crash", tags: ['schema-design', 'temporary', 'unlogged', 'comparison'] },
  { id: 'pg-schema-design-l3-081', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Foreign Keys', question: 'What is a circular foreign key dependency and how do you handle it?', options: ['Foreign keys that reference themselves', 'Two or more tables where each references the other, requiring DEFERRABLE constraints or nullable foreign keys to break the INSERT cycle', 'A foreign key chain through multiple tables', 'Circular dependencies are automatically resolved'], correctAnswer: 1, explanation: 'Circular foreign keys occur when table A references table B and table B references table A. You cannot insert into either without the other existing. Solutions include: making one FK nullable, using DEFERRABLE INITIALLY DEFERRED constraints, or restructuring the schema.', codeSnippet: "CREATE TABLE teams (\n  id SERIAL PRIMARY KEY,\n  captain_id INT  -- will reference players(id)\n);\n\nCREATE TABLE players (\n  id SERIAL PRIMARY KEY,\n  team_id INT REFERENCES teams(id)\n);\n\n-- Add deferred FK to break the cycle:\nALTER TABLE teams ADD CONSTRAINT fk_captain\n  FOREIGN KEY (captain_id) REFERENCES players(id)\n  DEFERRABLE INITIALLY DEFERRED;\n\nBEGIN;\nINSERT INTO teams (id) VALUES (1);\nINSERT INTO players (id, team_id) VALUES (10, 1);\nUPDATE teams SET captain_id = 10 WHERE id = 1;\nCOMMIT;  -- FK checked here", tags: ['schema-design', 'circular-dependency', 'deferrable'] },
  { id: 'pg-schema-design-l3-082', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is column tetris and why does it matter for PostgreSQL table design?', options: ['A game played with columns', 'Reordering columns by alignment requirements to minimize padding/wasted space due to PostgreSQL data type alignment rules', 'Dropping unused columns', 'Renaming columns alphabetically'], correctAnswer: 1, explanation: 'PostgreSQL aligns column data according to type-specific alignment requirements (1, 2, 4, or 8 bytes). Poor column ordering can waste bytes per row due to padding. Ordering columns from largest to smallest alignment minimizes wasted space, especially in tables with billions of rows.', codeSnippet: "-- Suboptimal order (potential padding):\nCREATE TABLE bad_order (\n  a BOOLEAN,    -- 1 byte + 7 bytes padding\n  b BIGINT,     -- 8 bytes (8-byte aligned)\n  c SMALLINT,   -- 2 bytes + 6 bytes padding\n  d BIGINT      -- 8 bytes (8-byte aligned)\n);  -- ~32 bytes per row\n\n-- Optimal order (minimize padding):\nCREATE TABLE good_order (\n  b BIGINT,     -- 8 bytes\n  d BIGINT,     -- 8 bytes\n  c SMALLINT,   -- 2 bytes\n  a BOOLEAN     -- 1 byte + no padding at end\n);  -- ~19 bytes per row", tags: ['schema-design', 'column-tetris', 'alignment', 'storage'] },
  { id: 'pg-schema-design-l3-083', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Normalization', question: 'What is Second Normal Form (2NF)?', options: ['All columns must be unique', 'A table is in 2NF if it is in 1NF and every non-key column depends on the entire composite primary key, not just part of it', 'Tables must have no foreign keys', 'All columns must have NOT NULL'], correctAnswer: 1, explanation: '2NF eliminates partial dependencies: every non-key attribute must depend on the whole primary key, not just a subset. This only applies to tables with composite primary keys. Tables with single-column primary keys are automatically in 2NF if they are in 1NF.', codeSnippet: "-- Violates 2NF: student_name depends only on student_id (part of PK)\nCREATE TABLE enrollments_bad (\n  student_id INT,\n  course_id INT,\n  student_name TEXT,  -- depends only on student_id!\n  grade CHAR(2),\n  PRIMARY KEY (student_id, course_id)\n);\n\n-- 2NF fix:\nCREATE TABLE students (student_id INT PRIMARY KEY, name TEXT);\nCREATE TABLE enrollments (\n  student_id INT REFERENCES students, course_id INT,\n  grade CHAR(2), PRIMARY KEY (student_id, course_id)\n);", tags: ['schema-design', 'normalization', '2nf'] },
  { id: 'pg-schema-design-l3-084', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is the purpose of FILLFACTOR in table creation?', options: ['Controls the fill color of the table', 'Sets the percentage of each page that should be filled with data, leaving space for in-page HOT updates to reduce bloat', 'Controls the maximum number of rows', 'Sets the compression ratio'], correctAnswer: 1, explanation: 'FILLFACTOR (default 100) controls how full each 8KB page is packed during INSERT/COPY. A lower value (e.g., 70) leaves free space for UPDATE operations to place new row versions on the same page (HOT updates), reducing table bloat and index maintenance.', codeSnippet: "-- Table with frequent updates: leave room for HOT updates\nCREATE TABLE accounts (\n  id SERIAL PRIMARY KEY,\n  balance NUMERIC(12,2) NOT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n) WITH (fillfactor = 70);\n\n-- 70% fill means 30% free space per page for updates\n-- HOT updates avoid creating new index entries", tags: ['schema-design', 'fillfactor', 'hot-updates', 'bloat'] },
  { id: 'pg-schema-design-l3-085', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Constraints', question: 'Can you create a cross-table constraint in PostgreSQL?', options: ['Yes, using CHECK constraints that reference other tables', 'No — CHECK constraints cannot reference other tables; use triggers or foreign keys for cross-table validation', 'Only with materialized views', 'Only with custom operators'], correctAnswer: 1, explanation: 'PostgreSQL CHECK constraints can only reference columns of the same table. For cross-table validation (e.g., ensuring a value exists in another table or checking aggregate conditions), use foreign keys, triggers, or application-level logic.', codeSnippet: "-- This FAILS: CHECK cannot reference other tables\nCREATE TABLE orders (\n  customer_id INT,\n  CHECK (customer_id IN (SELECT id FROM customers))  -- ERROR!\n);\n\n-- Use foreign key instead:\nCREATE TABLE orders (\n  customer_id INT REFERENCES customers(id)  -- correct\n);\n\n-- For complex cross-table logic, use a trigger:\nCREATE TRIGGER validate_order\n  BEFORE INSERT ON orders\n  FOR EACH ROW EXECUTE FUNCTION check_order_validity();", tags: ['schema-design', 'check-constraint', 'cross-table', 'limitations'] },
  { id: 'pg-schema-design-l3-086', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Table Design', question: 'What is row-level security (RLS) and how does it integrate with schema design?', options: ['Encrypting individual rows', 'A feature that applies filter policies to control which rows are visible/modifiable per user, enforced transparently by the database engine', 'Row-level locking', 'Access control on specific columns'], correctAnswer: 1, explanation: 'RLS allows you to define policies that filter which rows a user can SELECT, INSERT, UPDATE, or DELETE. Policies are applied transparently, even in views and functions. This is ideal for multi-tenant applications where tenant isolation must be guaranteed at the database level.', codeSnippet: "ALTER TABLE documents ENABLE ROW LEVEL SECURITY;\n\n-- Users can only see their own documents:\nCREATE POLICY user_docs_select ON documents\n  FOR SELECT\n  USING (owner_id = current_setting('app.user_id')::int);\n\n-- Users can only insert documents they own:\nCREATE POLICY user_docs_insert ON documents\n  FOR INSERT\n  WITH CHECK (owner_id = current_setting('app.user_id')::int);\n\n-- Force RLS even for table owners:\nALTER TABLE documents FORCE ROW LEVEL SECURITY;", tags: ['schema-design', 'rls', 'row-level-security', 'multi-tenant'] },
  { id: 'pg-schema-design-l3-087', language: 'postgresql', level: 'level3', category: 'Schema Design', subcategory: 'Generated Columns', question: 'Can you ALTER a regular column to become a generated column?', options: ['Yes, with ALTER COLUMN ... SET GENERATED', 'No — you cannot change an existing column to generated or vice versa; you must drop and re-add the column or create a new table', 'Only if the column is empty', 'Only for TEXT columns'], correctAnswer: 1, explanation: 'PostgreSQL does not support converting an existing column to a generated column or vice versa. To add a generated column replacing a regular column, you must drop the old column and add a new generated column, potentially requiring data migration.', codeSnippet: "-- Cannot convert existing column to generated:\n-- ALTER TABLE t ALTER COLUMN x SET GENERATED ALWAYS AS (expr) STORED;\n-- ERROR: not supported\n\n-- Workaround: add new column, migrate, rename\nALTER TABLE products ADD COLUMN total_new\n  NUMERIC GENERATED ALWAYS AS (price * quantity) STORED;\n\nALTER TABLE products DROP COLUMN total;\nALTER TABLE products RENAME COLUMN total_new TO total;", tags: ['schema-design', 'generated-columns', 'alter-column', 'limitations'] },
];

export default questions;
